  "61-programacion i-desarrollo-explica la diferencia entre un lenguaje de programacion de alto nivel y ": {
    "reference": "Un lenguaje de alto nivel (Python, Java, C#) usa sintaxis cercana al lenguaje humano, es portable y fácil de mantener, pero requiere compilación o interpretación. Un lenguaje de bajo nivel (ensamblador) está cercano al lenguaje máquina, es específico del hardware, más rápido pero difícil de escribir y mantener.",
    "explanation": "El alto nivel prioriza productividad y portabilidad; el bajo nivel prioriza rendimiento y control directo del hardware."
  },
  "62-programacion i-desarrollo-describe la diferencia entre programacion estructurada y programacion or": {
    "reference": "La programación estructurada organiza el código mediante secuencias, condicionales y bucles, sin clases. La POO organiza el código alrededor de objetos y clases. Ventajas de la POO: encapsulamiento (oculta detalles internos), herencia (reutilización de código), polimorfismo (un mismo método, múltiples comportamientos) y abstracción (modela el dominio).",
    "explanation": "La POO favorece la modularidad, reutilización y mantenibilidad, especialmente en proyectos grandes; la estructurada es más simple pero menos escalable."
  },
  "63-programacion i-desarrollo-explica que es un bucle en programacion y proporciona ejemplos de bucles": {
    "reference": "Un bucle es una estructura de control que repite un bloque de código mientras se cumpla una condición. Ejemplos: Python → for i in range(5): print(i); Java → for(int i=0;i<5;i++){...}; JavaScript → while(i<5){i++;}.",
    "explanation": "Los bucles permiten automatizar tareas repetitivas sin duplicar código, controlando el flujo según una condición."
  },
  "64-programacion i-desarrollo-describe el proceso de debugging en programacion y menciona algunas herr": {
    "reference": "El debugging consiste en detectar, localizar y corregir errores en el código. Herramientas: depuradores visuales (gdb, el de Visual Studio, pdb de Python), puntos de interrupción (breakpoints), inspección de variables, ejecución paso a paso, logs y trazas, pruebas unitarias.",
    "explanation": "Estas herramientas permiten observar el estado del programa en ejecución, aislar el origen del fallo y verificar la corrección."
  },
  "65-programacion i-desarrollo-que es un algoritmo en programacion y cual es su importancia proporciona": {
    "reference": "Un algoritmo es una secuencia finita y ordenada de instrucciones precisas que resuelve un problema. Su importancia radica en que permite resolver problemas de forma sistemática, reproducible y eficiente. Ejemplo: el algoritmo de búsqueda binaria encuentra un elemento en un arreglo ordenado dividiendo el rango a la mitad en cada paso.",
    "explanation": "Los algoritmos son la base de la programación: sin un algoritmo claro, no se puede codificar una solución correcta y eficiente."
  },
  "66-programacion i-desarrollo-que es un ide en programacion y como puede ayudar a los programadores en": {
    "reference": "Un IDE (Integrated Development Environment) es una aplicación que integra editor de código, compilador/intérprete, depurador, autocompletado, resaltado de sintaxis y herramientas de gestión de proyectos. Facilita la productividad al reunir todo lo necesario en un solo entorno.",
    "explanation": "El IDE ahorra tiempo y reduce errores al ofrecer herramientas integradas: autocompletado, refactorización, control de versiones y depuración visual."
  },
  "67-programacion i-desarrollo-explica la importancia de los comentarios en el codigo fuente y como deb": {
    "reference": "Los comentarios documentan el propósito del código, facilitan su mantenimiento y permiten que otros programadores entiendan la lógica. Deben ser claros, breves, explicar el 'por qué' (no el 'qué', que ya lo dice el código) y mantenerse actualizados al modificar el código.",
    "explanation": "Comentarios obsoletos o redundantes confunden más de lo que ayudan; deben aportar contexto, no repetir lo evidente."
  },
  "68-programacion i-desarrollo-que es la recursion en programacion y cuando es apropiado utilizarla pro": {
    "reference": "La recursión es una técnica donde una función se llama a sí misma para resolver subproblemas más pequeños del mismo tipo, hasta llegar a un caso base que detiene la recursión. Es apropiada en problemas naturalmente recursivos como árboles, factorial, Fibonacci o recorrido de grafos. Ejemplo: factorial(n) = n * factorial(n-1), con caso base factorial(0) = 1.",
    "explanation": "La recursión simplifica el código de problemas dividibles, pero consume memoria de pila y puede ser menos eficiente que una versión iterativa si no se optimiza."
  },
  "69-programacion i-desarrollo-describe la diferencia entre una variable local y una variable global en": {
    "reference": "Una variable local se declara dentro de una función o bloque y solo existe en ese ámbito; se destruye al salir. Una variable global se declara fuera de toda función y es accesible desde cualquier parte del programa. La local limita efectos secundarios; la global facilita compartir estado pero dificulta el mantenimiento.",
    "explanation": "El alcance (scope) controla visibilidad y vida de la variable. Las locales son más seguras, las globales pueden causar acoplamiento y errores difíciles de rastrear."
  },
  "70-programacion i-desarrollo-que es la programacion concurrente y cual es su importancia en el desarr": {
    "reference": "La programación concurrente ejecuta múltiples hilos o procesos aparentemente al mismo tiempo, mejorando el rendimiento y la respuesta del sistema. Es útil en servidores web, interfaces gráficas, operaciones de E/S y simulaciones. Ejemplo: un servidor web que atiende varias peticiones HTTP simultáneamente usando hilos.",
    "explanation": "La concurrencia aprovecha tiempos muertos (por ejemplo, esperando E/S) para avanzar con otras tareas, mejorando el uso de la CPU y la experiencia del usuario."
  },
