  "101-hardware de computadoras-desarrollo-describe la funcion de la cpu unidad central de procesamiento en una com": {
    "reference": "La CPU ejecuta instrucciones y realiza cálculos. Sus componentes clave son: la Unidad de Control (UC), que coordina y dirige las operaciones; la Unidad Aritmético Lógica (ALU), que realiza operaciones matemáticas y lógicas; y los registros, pequeñas memorias ultrarrápidas dentro de la CPU.",
    "explanation": "La CPU es el cerebro del sistema: sin UC no habría coordinación y sin ALU no habría cálculos."
  },
  "102-hardware de computadoras-desarrollo-explica la diferencia entre la memoria ram y el almacenamiento de disco ": {
    "reference": "La RAM es memoria volátil de acceso ultrarrápido que guarda temporalmente datos y programas en uso; pierde su contenido al apagar. El disco duro (HDD/SSD) es almacenamiento no volátil de larga duración que retiene los datos sin energía, pero es más lento que la RAM.",
    "explanation": "La RAM prioriza velocidad para que la CPU acceda rápido; el disco prioriza persistencia para conservar datos."
  },
  "103-hardware de computadoras-desarrollo-describe como funciona un disco de estado solido ssd y cuales son sus ve": {
    "reference": "Un SSD almacena datos en celdas de memoria flash NAND, sin partes móviles. Frente a un HDD, un SSD es más rápido (lecturas/escrituras en milisegundos vs. décimas de segundo), silencioso, consume menos energía, es más resistente a golpes y alarga la duración de la batería en portátiles.",
    "explanation": "La ausencia de partes mecánicas elimina tiempos de búsqueda mecánica, acelerando drásticamente el acceso a los datos."
  },
  "104-hardware de computadoras-desarrollo-explica el proposito de la placa madre placa base en una computadora y m": {
    "reference": "La placa madre es la placa principal que conecta y permite la comunicación entre todos los componentes: CPU, RAM, disco, GPU, fuentes, periféricos. Componentes principales: socket de CPU, ranuras RAM (DIMM), chipset (northbridge/southbridge), conectores de almacenamiento (SATA/M.2), puertos de expansión (PCIe) y puertos traseros (USB, red, audio).",
    "explanation": "Es el esqueleto del sistema: define qué componentes se pueden instalar y cómo se comunican entre sí."
  },
  "105-hardware de computadoras-desarrollo-explica como funcionan los ventiladores de cpu y por que son esenciales ": {
    "reference": "Los ventiladores de CPU extraen el calor generado por el procesador y lo expulsan fuera del equipo, manteniendo la temperatura en rangos seguros. Son esenciales porque el sobrecalentamiento degrada el rendimiento (thermal throttling), reduce la vida útil del componente e incluso puede quemarlo.",
    "explanation": "Sin ventilación adecuada la CPU se apagaría por protección o se dañaría permanentemente."
  },
  "106-hardware de computadoras-desarrollo-describe la funcion de la bios sistema basico de entrada salida en una c": {
    "reference": "La BIOS es un firmware almacenado en ROM que realiza el POST (Power-On Self Test), inicializa el hardware y localiza el sistema operativo en el disco para cargarlo en RAM. Es el primer software que se ejecuta al encender.",
    "explanation": "Sin BIOS, la computadora no sabría cómo iniciar sus componentes ni dónde encontrar el sistema operativo."
  },
  "107-hardware de computadoras-desarrollo-explica como funcionan las tarjetas de video gpu en una computadora y su": {
    "reference": "La GPU procesa imágenes y gráficos: calcula píxeles, texturas, sombras e iluminación y los envía al monitor. Es vital para videojuegos, edición de video, diseño 3D y recientemente para inteligencia artificial y cómputo paralelo.",
    "explanation": "La GPU está optimizada para operaciones paralelas masivas, descargando de la CPU el trabajo gráfico y mejorando el rendimiento visual."
  },
  "108-hardware de computadoras-desarrollo-describe la funcion de una fuente de alimentacion en una computadora y c": {
    "reference": "La fuente de alimentación (PSU) convierte la corriente alterna (CA) de la red eléctrica en corriente continua (CC) de distintos voltajes (3.3V, 5V, 12V) y la distribuye a cada componente: placa madre, CPU, disco, GPU, ventiladores.",
    "explanation": "Sin una fuente estable, los componentes no tendrían la energía regulada que necesitan y podrían dañarse por picos de voltaje."
  },
  "109-hardware de computadoras-desarrollo-explica el proposito de la tarjeta de red nic en una computadora y como ": {
    "reference": "La tarjeta de red (NIC) permite a la computadora conectarse a una red (cableada con RJ-45 o inalámbrica Wi-Fi). Maneja la transmisión y recepción de paquetes, controla el acceso al medio físico y se identifica con una dirección MAC única.",
    "explanation": "Sin NIC, la computadora no podría comunicarse con otros equipos, acceder a Internet o compartir recursos."
  },
  "110-hardware de computadoras-desarrollo-describe el proposito de la memoria cache en una cpu y como contribuye a": {
    "reference": "La memoria caché es una memoria ultrarrápida y pequeña ubicada dentro o cerca de la CPU. Guarda los datos e instrucciones más usados para que la CPU no tenga que leerlos de la RAM (más lenta) en cada acceso, mejorando notablemente el rendimiento.",
    "explanation": "Reduce la brecha de velocidad entre la CPU (rápida) y la RAM (lenta), evitando ciclos de espera."
  },
