  "141-taller de sistemas operativos-desarrollo-describe en detalle el concepto de procesos en un sistema operativo y co": {
    "reference": "Un proceso es una instancia de un programa en ejecución, con su propio espacio de direcciones, contador de programa, registros y recursos asignados. El SO lo gestiona mediante el PCB (Process Control Block) que almacena su estado (nuevo, listo, ejecutando, esperando, terminado). La planificación del CPU decide qué proceso corre en cada momento.",
    "explanation": "Sin procesos el SO no podría gestionar múltiples tareas concurrentemente ni aislar fallos entre programas."
  },
  "142-taller de sistemas operativos-desarrollo-explica el concepto de multiprocesamiento y multiprocesadores en un sist": {
    "reference": "El multiprocesamiento es la capacidad de un SO de usar múltiples CPUs para ejecutar varios procesos en paralelo real. Los multiprocesadores son sistemas con más de una CPU (multi-core o multi-CPU). Beneficios: mayor rendimiento, paralelismo real, mejor respuesta y tolerancia a fallos.",
    "explanation": "Varios núcleos permiten ejecutar tareas realmente en paralelo, no solo concurrente, mejorando rendimiento en cargas pesadas."
  },
  "143-taller de sistemas operativos-desarrollo-que es la administracion de archivos en un sistema operativo describe la": {
    "reference": "La administración de archivos organiza cómo se almacenan, nombran, 保护和 recuperan los datos en disco. Estructuras usadas: tablas de asignación (FAT, MFT en NTFS, inodos en Unix/Linux), directorios jerárquicos en árbol, descriptores de archivo y metadatos (permisos, fechas, tamaño).",
    "explanation": "Sin administración de archivos no habría forma estructurada de guardar, localizar o proteger los datos en el disco."
  },
  "144-taller de sistemas operativos-desarrollo-cual es el proposito de la administracion de memoria en un sistema opera": {
    "reference": "La administración de memoria gestiona la asignación y liberación de memoria a los procesos, evitando conflictos y optimizando el uso. Esquemas: paginación (divide memoria en páginas fijas), segmentación (segmentos de tamaño variable), memoria virtual (swap), y esquemas híbridos segmentación paginada.",
    "explanation": "Permite ejecutar varios procesos simultáneamente aunque la RAM física sea insuficiente, mediante técnicas como paginación y memoria virtual."
  },
  "145-taller de sistemas operativos-desarrollo-explica el concepto de comunicacion entre procesos en un sistema operati": {
    "reference": "La comunicación entre procesos (IPC) permite que procesos intercambien datos y sincronicen sus acciones. Mecanismos: pipes (tuberías), named pipes, message queues (colas de mensajes), shared memory (memoria compartida), semaphores (semaforos), sockets y señales.",
    "explanation": "Sin IPC, los procesos quedarían aislados y no podrían colaborar en tareas conjuntas como servidores, pipelines o aplicaciones distribuidas."
  },
  "146-taller de sistemas operativos-desarrollo-que son los sistemas de archivos distribuidos y cual es su importancia e": {
    "reference": "Un sistema de archivos distribuido (DFS) permite acceder a archivos almacenados en múltiples servidores como si estuvieran en una sola máquina. Importancia: escalabilidad, tolerancia a fallos y disponibilidad. Ejemplos: NFS (Network File System), SMB/CIFS, HDFS (Hadoop DFS), GlusterFS, CephFS.",
    "explanation": "Permiten compartir y acceder a gran escala a archivos sin que el usuario sepa en qué servidor están realmente."
  },
  "147-taller de sistemas operativos-desarrollo-describe la importancia de la virtualizacion en sistemas operativos como": {
    "reference": "La virtualización permite ejecutar múltiples sistemas operativos o entornos sobre un mismo hardware físico mediante un hypervisor (VMware, VirtualBox, KVM, Hyper-V). La virtualización de hardware simula CPU, RAM, disco y red; la virtualización de software usa contenedores (Docker) que comparten el kernel del host.",
    "explanation": "Permite consolidar servidores, aislar entornos, mejorar la utilización del hardware y facilitar la portabilidad de aplicaciones."
  },
  "148-taller de sistemas operativos-desarrollo-que es la administracion de entrada salida en sistemas operativos explic": {
    "reference": "La administración de E/S gestiona la comunicación entre el SO y los dispositivos (teclado, disco, red, impresora). Usa controladores (drivers), buffers, caché, planificación de E/S e interrupciones. Los conflictos (mismo puerto o IRQ) se resuelven mediante asignación dinámica de recursos y controladores estandarizados (Plug & Play).",
    "explanation": "Sin gestión de E/S, los dispositivos no podrían comunicarse con la CPU ni compartir recursos sin conflictos."
  },
  "149-taller de sistemas operativos-desarrollo-describe las estrategias de planificacion de cpu utilizadas en sistemas ": {
    "reference": "Las estrategias de planificación de CPU deciden qué proceso ejecuta en cada momento. Principales: FCFS (First-Come First-Served), simple pero con efecto convoy; SJF (Shortest Job First), óptimo en promedio pero requiere predecir duración; Round Robin (RR), justo y reactivo; Prioridades; Multinivel con retroalimentación.",
    "explanation": "Cada estrategia equilibra fairness, throughput, tiempo de respuesta y utilización de CPU de manera distinta."
  },
  "150-taller de sistemas operativos-desarrollo-explica el concepto de concurrencia en un sistema operativo y como se ge": {
    "reference": "La concurrencia es la capacidad de ejecutar múltiples procesos/hilos al mismo tiempo, cooperando o compitiendo por recursos. Los problemas clásicos son: exclusión mutua, condiciones de carrera (race conditions), interbloqueo (deadlock) y inanición. Se resuelven con semáforos, mutexes, monitores y algoritmos de sincronización.",
    "explanation": "Sin mecanismos de sincronización, los procesos concurrentes podrían corromper datos compartidos o bloquearse mutuamente."
  },
