  "181-ofimatica y tecnologia y multimedia-desarrollo-describe los pasos basicos para crear una presentacion de diapositivas e": {
    "reference": "Pasos básicos: 1) Definir el objetivo y la audiencia; 2) Estructurar el contenido en diapositivas claras (introducción, desarrollo, conclusión); 3) Usar plantillas coherentes y poco texto por diapositiva; 4) Incorporar imágenes y gráficos relevantes; 5) Aplicar transiciones y animaciones moderadas; 6) Revisar ortografía y contrastes; 7) Ensayar la exposición.",
    "explanation": "Una presentación efectiva equilibra claridad, brevedad y apoyo visual; el exceso de texto o animaciones distrae al espectador."
  },
  "182-ofimatica y tecnologia y multimedia-desarrollo-explica la diferencia entre los formatos de archivo jpeg y png para imag": {
    "reference": "JPEG comprime con pérdida: reduce tamaño eliminando información visual poco perceptible, ideal para fotografías web. PNG comprime sin pérdida y soporta transparencia alfa, ideal para logotipos, gráficos con áreas transparentes o imágenes que requieren alta calidad y bordes definidos.",
    "explanation": "Usar JPEG para fotos en web; PNG cuando se necesita transparencia, texto nítido o no se puede perder calidad."
  },
  "183-ofimatica y tecnologia y multimedia-desarrollo-por que es importante realizar copias de seguridad de tus datos y como s": {
    "reference": "Las copias de seguridad protegen contra pérdida de datos por fallos de hardware, errores humanos, virus, robo o desastres. Para hacerlas efectivas: seguir la regla 3-2-1 (3 copias, 2 medios distintos, 1 fuera del sitio), automatizarlas, verificarlas periódicamente y guardarlas cifradas.",
    "explanation": "Sin backups, un fallo único puede significar la pérdida irrecuperable de años de información personal o profesional."
  },
  "184-ofimatica y tecnologia y multimedia-desarrollo-describe como funcionan los programas de edicion de video y menciona alg": {
    "reference": "Los editores de video permiten: importar clips, cortar y unir segmentos, aplicar transiciones y efectos visuales, añadir pistas de audio, subtítulos, corrección de color y exportar a múltiples formatos y resoluciones. Características clave: línea de tiempo multicapa, render acelerado por GPU, soporte 4K/8K.",
    "explanation": "Sin estas herramientas, la edición de video requería procesos analógicos lentos y costosos; hoy es accesible y profesional."
  },
  "185-ofimatica y tecnologia y multimedia-desarrollo-explica la diferencia entre un documento de procesamiento de texto y una": {
    "reference": "Un documento de texto (Word) está orientado a redacción lineal con párrafos y formato, ideal para informes, cartas o ensayos. Una hoja de cálculo (Excel) está orientada a datos tabulares, cálculos y análisis, ideal para presupuestos, inventarios, fórmulas y gráficos.",
    "explanation": "Word para narrativa, Excel para datos y cálculos; usar el adecuado según el contenido."
  },
  "186-ofimatica y tecnologia y multimedia-desarrollo-que son los documentos pdf y cual es su ventaja principal en comparacion": {
    "reference": "PDF (Portable Document Format) es un formato que conserva el diseño, fuentes, imágenes y estructura del documento original. Su ventaja principal es que se visualiza igual en cualquier plataforma, dispositivo o sistema operativo, sin que el receptor pueda modificar fácilmente el contenido.",
    "explanation": "Es el estándar para compartir documentos finales (contratos, facturas, libros) porque garantiza fidelidad y portabilidad."
  },
  "187-ofimatica y tecnologia y multimedia-desarrollo-describe como se puede mejorar la seguridad de los documentos electronic": {
    "reference": "Para mejorar la seguridad de documentos y presentaciones: usar contraseñas y cifrado, marcas de agua, permisos (solo lectura, sin impresión), firmas digitales, evitar macros sospechosas, actualizar software, usar HTTPS al compartir, y verificar destinatarios antes de enviar.",
    "explanation": "Sin seguridad adecuada, cualquier persona podría modificar, copiar o distribuir documentos sin autorización."
  },
  "188-ofimatica y tecnologia y multimedia-desarrollo-cual es la importancia de la accesibilidad en documentos y presentacione": {
    "reference": "La accesibilidad garantiza que personas con discapacidades (visuales, auditivas, motoras) puedan usar el contenido. Prácticas: texto alternativo en imágenes, contrastes adecuados, subtítulos en videos, estructura de encabezados, fuentes legibles, navegación por teclado y compatibilidad con lectores de pantalla.",
    "explanation": "Sin accesibilidad, parte de la audiencia queda excluida; además, en muchos países es requisito legal para sitios públicos."
  },
  "189-ofimatica y tecnologia y multimedia-desarrollo-explica que es la compresion de datos y por que se utiliza en archivos m": {
    "reference": "La compresión de datos reduce el tamaño de un archivo eliminando redundancia. Con pérdida (JPEG, MP3, MP4) descarta información poco perceptible, reduciendo calidad. Sin pérdida (PNG, FLAC, ZIP) reconstruye el archivo original sin pérdidas. Efectos: menor espacio y ancho de banda, pero posible pérdida de fidelidad.",
    "explanation": "La compresión equilibra tamaño y calidad; elegir el tipo según el caso de uso."
  },
  "190-ofimatica y tecnologia y multimedia-desarrollo-como se pueden utilizar las herramientas de colaboracion en linea para t": {
    "reference": "Las herramientas de colaboración en línea permiten a varias personas trabajar simultáneamente en documentos y proyectos multimedia. Ejemplos: Google Workspace (Docs, Sheets, Slides), Microsoft 365 (Word, Excel, PowerPoint Online), Notion, Figma (diseño colaborativo), Slack y Trello para coordinación.",
    "explanation": "Permiten edición simultánea, comentarios, control de versiones y comunicación en tiempo real, sin importar la ubicación de los colaboradores."
  },
