  "221-diseno y programacion web i-desarrollo-explica brevemente la diferencia entre html y css en el desarrollo web": {
    "reference": "HTML define la estructura y el contenido de la página (textos, imágenes, enlaces, formularios). CSS define el estilo y la presentación (colores, fuentes, layout, animaciones). HTML es el esqueleto; CSS es la piel y el diseño visual.",
    "explanation": "HTML organiza qué se muestra; CSS define cómo se ve. Separarlos facilita el mantenimiento y la reutilización."
  },
  "222-diseno y programacion web i-desarrollo-describe el proposito de javascript en el desarrollo web y proporciona u": {
    "reference": "JavaScript añade interactividad y dinamismo a una página web: responde a eventos, manipula el DOM, valida formularios y hace peticiones asíncronas (AJAX). Ejemplo: un botón que al hacer clic cambia el color de fondo: document.getElementById('btn').onclick = () => document.body.style.background = 'lightblue';",
    "explanation": "Sin JavaScript, la página sería estática; con JS reacciona al usuario sin recargar la página."
  },
  "223-diseno y programacion web i-desarrollo-explica que es un servidor web y como se diferencia de un servidor de ap": {
    "reference": "Un servidor web (Apache, Nginx) sirve contenido estático (HTML, CSS, imágenes) a través de HTTP. Un servidor de aplicaciones (Tomcat, Node.js, Django) ejecuta lógica del lado del servidor, procesa peticiones dinámicas, accede a bases de datos y genera respuestas personalizadas.",
    "explanation": "El servidor web entrega archivos; el de aplicaciones genera contenido dinámico con lógica de negocio."
  },
  "224-diseno y programacion web i-desarrollo-describe la diferencia entre una cookie de sesion y una cookie persisten": {
    "reference": "Una cookie de sesión se almacena temporalmente y se elimina al cerrar el navegador; sirve para mantener el estado durante una sesión (carrito de compras, login temporal). Una cookie persistente tiene fecha de expiración y permanece tras cerrar el navegador; sirve para recordar preferencias o identificar al usuario en visitas futuras.",
    "explanation": "Las de sesión son efímeras y seguras para autenticación; las persistentes permiten personalización a largo plazo pero requieren cuidado con la privacidad."
  },
  "225-diseno y programacion web i-desarrollo-explica que es el dom modelo de objeto del documento en el contexto del ": {
    "reference": "El DOM (Document Object Model) es una representación en forma de árbol de la estructura HTML de una página. JavaScript lo utiliza para acceder, modificar, añadir o eliminar elementos y atributos dinámicamente, sin recargar la página.",
    "explanation": "El DOM permite que JavaScript manipule la página en tiempo real, haciendo sitios dinámicos e interactivos."
  },
  "226-diseno y programacion web i-desarrollo-describe que es un marco de diseno framework en el desarrollo web y prop": {
    "reference": "Un framework de diseño es un conjunto de herramientas, componentes y estilos preconstruidos que facilitan el desarrollo web responsivo. Ejemplos: Bootstrap (HTML/CSS/JS), Foundation, Tailwind CSS, Materialize (basado en Material Design de Google), Bulma.",
    "explanation": "Aceleran el desarrollo al ofrecer componentes listos y patrones de diseño consistentes y responsivos."
  },
  "227-diseno y programacion web i-desarrollo-que es ajax en el desarrollo web y como se utiliza para cargar datos de ": {
    "reference": "AJAX (Asynchronous JavaScript And XML) permite actualizar partes de una página web sin recargarla, intercambiando datos con el servidor en segundo plano. Se usa para cargar contenido dinámico, validar formularios, autocomplete, notificaciones. Hoy se implementa con fetch() o XMLHttpRequest.",
    "explanation": "AJAX mejora la experiencia del usuario al permitir actualizaciones parciales y asíncronas sin interrumpir la navegación."
  },
  "228-diseno y programacion web i-desarrollo-explica como se utiliza el atributo hreflang en las etiquetas link o a e": {
    "reference": "El atributo hreflang indica el idioma y región geográfica de una página o recurso vinculado. En <link> se usa para señalar versiones alternativas de la página en otros idiomas (SEO internacional). En <a> indica el idioma/region del destino del enlace.",
    "explanation": "Mejora el SEO multilingüe y ayuda a los buscadores a servir la versión correcta según el idioma del usuario."
  },
  "229-diseno y programacion web i-desarrollo-describe que es una api restful en el contexto del desarrollo web y como": {
    "reference": "Una API RESTful es una interfaz que sigue los principios de REST (Representational State Transfer) para acceder y manipular recursos mediante métodos HTTP: GET (leer), POST (crear), PUT/PATCH (actualizar), DELETE (eliminar). Usa URLs claras y devuelve datos en JSON.",
    "explanation": "Permite que distintas aplicaciones se comuniquen mediante HTTP de forma estándar, escalable y stateless."
  },
  "230-diseno y programacion web i-desarrollo-que es el responsive design diseno responsivo en el desarrollo web y por": {
    "reference": "El responsive design es una técnica que adapta el diseño de una página web al tamaño de la pantalla del dispositivo (escritorio, tablet, móvil). Es importante porque la mayoría del tráfico web proviene de móviles, mejora la experiencia del usuario y el SEO. Se logra con media queries de CSS, layouts flexibles (Flexbox, Grid) e imágenes fluidas.",
    "explanation": "Sin responsive design, el sitio se vería roto o sería difícil de usar en móviles, perdiendo usuarios y posicionamiento."
  },
