  "261-estadistica-desarrollo-que es el experimento aleatorio": {
    "reference": "Un experimento aleatorio es aquel cuyo resultado no se puede predecir con certeza antes de realizarlo, aunque se conocen todos los resultados posibles. Ejemplo: lanzar un dado, lanzar una moneda.",
    "explanation": "El azar impide predecir el resultado exacto; solo se pueden asignar probabilidades a cada resultado posible."
  },
  "262-estadistica-desarrollo-que es el espacio muestral": {
    "reference": "El espacio muestral (Ω) es el conjunto de todos los resultados posibles de un experimento aleatorio. Ejemplo: al lanzar un dado, Ω = {1, 2, 3, 4, 5, 6}.",
    "explanation": "Es el universo de resultados posibles sobre el cual se definen los eventos y se calculan las probabilidades."
  },
  "263-estadistica-desarrollo-mencione las formas de presentacion del espacio muestral": {
    "reference": "Formas de presentación del espacio muestral: 1) Por extensión o lista (enumerar todos los resultados, ej. {1,2,3,4,5,6}); 2) Por comprensión (describir la propiedad, ej. {x | x es entero entre 1 y 6}); 3) Mediante diagrama de árbol (útil para experimentos compuestos); 4) Tabla de doble entrada (para experimentos con dos variables).",
    "explanation": "Cada forma facilita la visualización y el cálculo de probabilidades según la complejidad del experimento."
  },
  "264-estadistica-desarrollo-que es una entrevista": {
    "reference": "Una entrevista es una técnica cualitativa de recolección de datos en la que el investigador formula preguntas abiertas a una persona para obtener información detallada sobre un tema. Puede ser estructurada, semiestructurada o en profundidad.",
    "explanation": "Permite obtener información rica y contextual que un cuestionario no podría capturar, mediante diálogo directo."
  },
  "265-estadistica-desarrollo-que es una encuesta": {
    "reference": "Una encuesta es un instrumento de recolección de datos que consiste en un conjunto de preguntas (abiertas o cerradas) aplicadas a una muestra representativa de la población, con el fin de obtener información cuantitativa o cualitativa sobre un tema específico.",
    "explanation": "Las encuestas permiten obtener datos de muchas personas de forma estandarizada, posibilitando análisis estadístico."
  },
  "266-estadistica-desarrollo-que son los parametros estadisticos": {
    "reference": "Los parámetros estadísticos son valores numéricos que resumen una característica de toda una población, como la media poblacional (μ), la varianza poblacional (σ²) o la proporción poblacional (p). Se diferencian de los estadísticos, que se calculan sobre muestras.",
    "explanation": "Los parámetros describen a la población completa y generalmente son desconocidos; se estiman a partir de estadísticos muestrales."
  },
  "267-estadistica-desarrollo-que es la estadistica": {
    "reference": "La estadística es la ciencia que recopila, organiza, presenta, analiza e interpreta datos para extraer información y tomar decisiones. Se divide en descriptiva (resumir datos) e inferencial (generalizar de la muestra a la población).",
    "explanation": "Permite transformar datos crudos en conocimiento útil para la toma de decisiones en ciencia, industria y gobierno."
  },
  "268-estadistica-desarrollo-que son las frecuencias absolutas": {
    "reference": "Las frecuencias absolutas (fᵢ) son el número de veces que aparece cada valor o categoría en un conjunto de datos. Indican el conteo bruto de ocurrencias.",
    "explanation": "Son la base para calcular las frecuencias relativas, acumuladas y los gráficos estadísticos."
  },
  "269-estadistica-desarrollo-que son las frecuencias relativas": {
    "reference": "Las frecuencias relativas (hᵢ) son el cociente entre la frecuencia absoluta y el total de datos: hᵢ = fᵢ / n. Expresan la proporción o porcentaje que representa cada valor respecto al total.",
    "explanation": "Permiten comparar conjuntos de distinto tamaño y se interpretan como probabilidades empíricas."
  },
  "270-estadistica-desarrollo-cual es la importancia de la estadistica": {
    "reference": "La importancia de la estadística radica en que permite tomar decisiones basadas en datos en lugar de intuición, identificar tendencias, evaluar hipótesis, predecir comportamientos y fundamentar políticas en ciencia, economía, medicina, ingeniería y gobierno.",
    "explanation": "Sin estadística, las decisiones se tomarían con base en intuición o anécdotas; con estadística, se basan en evidencia objetiva."
  },
