  "301-programacion ii-desarrollo-describa brevemente que es la programacion orientada a objetos y mencion": {
    "reference": "La POO es un paradigma que modela el software mediante objetos que combinan estado (atributos) y comportamiento (métodos). Sus cuatro pilares son: encapsulamiento (ocultar detalles internos), herencia (reutilizar código de la clase base), polimorfismo (un mismo método con distintas formas) y abstracción (modelar solo lo esencial).",
    "explanation": "Los cuatro pilares permiten construir software modular, reutilizable, mantenible y escalable."
  },
  "302-programacion ii-desarrollo-explique que es la herencia en programacion orientada a objetos y como s": {
    "reference": "La herencia permite que una clase (subclase) adquiera atributos y métodos de otra (superclase). En Java se implementa con la palabra clave extends: class Perro extends Animal {...}. La subclase puede añadir métodos nuevos o sobrescribir los heredados (@Override).",
    "explanation": "La herencia favorece la reutilización y la jerarquía natural del dominio, evitando duplicar código."
  },
  "303-programacion ii-desarrollo-que es una interfaz en java y como difiere de una clase abstracta": {
    "reference": "Una interfaz en Java es un contrato que declara métodos abstractos (y constantes) que las clases deben implementar. Una clase abstracta puede tener métodos concretos, atributos de instancia y constructores, mientras que una interfaz clásicamente solo define firmas de métodos (Java 8+ permite default y static methods).",
    "explanation": "Las interfaces definen contratos puros y permiten simular herencia múltiple; las clases abstractas aportan implementación parcial compartida."
  },
  "304-programacion ii-desarrollo-describa el proposito y uso del bloque finally en el manejo de excepcion": {
    "reference": "El bloque finally se ejecuta siempre, sin importar si se lanzó o no una excepción en el bloque try. Se usa para liberar recursos: cerrar archivos, conexiones a base de datos, sockets, etc., garantizando su liberación incluso si ocurre un error.",
    "explanation": "Garantiza limpieza de recursos en cualquier escenario, evitando fugas de memoria o conexiones abiertas."
  },
  "305-programacion ii-desarrollo-explique que son las consultas preparadas y como ayudan a prevenir la in": {
    "reference": "Las consultas preparadas (PreparedStatement) son sentencias SQL precompiladas en las que los parámetros se pasan por separado usando marcadores (?). Como el SQL ya está compilado, los datos del usuario no pueden alterar la estructura de la consulta, evitando así la inyección SQL.",
    "explanation": "Al separar código SQL de datos, los ataques de inyección se vuelven inútiles: el usuario envía datos, no comandos."
  },
  "306-programacion ii-desarrollo-que son los genericos en java y cual es su beneficio principal": {
    "reference": "Los genéricos en Java permiten escribir clases, interfaces y métodos que operan sobre tipos especificados como parámetros (<T>, <E>, <K,V>). Beneficio principal: reutilización y seguridad de tipos en tiempo de compilación, evitando casts explícitos y errores ClassCastException.",
    "explanation": "Con genéricos, una misma clase (List<T>) sirve para List<String>, List<Integer>, etc., con verificación de tipos en compilación."
  },
  "307-programacion ii-desarrollo-describa que es un hilo thread en programacion y como se puede crear un ": {
    "reference": "Un hilo (thread) es la unidad mínima de ejecución dentro de un proceso, permitiendo concurrencia. En Java se crea extendiendo Thread y sobrescribiendo run(), o implementando Runnable y pasándolo a un Thread: Thread t = new Thread(new MiRunnable()); t.start();",
    "explanation": "Los hilos permiten ejecutar tareas concurrentemente dentro de un mismo programa, mejorando el rendimiento en operaciones de E/S o paralelas."
  },
  "308-programacion ii-desarrollo-explique que es la inyeccion de dependencias dependency injection y su p": {
    "reference": "La inyección de dependencias (DI) es un patrón en el que un objeto recibe sus dependencias desde fuera (inyectadas) en lugar de crearlas internamente. Su propósito es reducir el acoplamiento, facilitar las pruebas unitarias (mocks) y promover la responsabilidad única.",
    "explanation": "Sin DI, los objetos crean sus dependencias, acoplando el código; con DI, las dependencias se inyectan vía constructor, setter o framework (Spring)."
  },
  "309-programacion ii-desarrollo-que es una spa single page application y cuales son sus ventajas": {
    "reference": "Una SPA (Single Page Application) es una aplicación web que carga una sola página HTML y actualiza dinámicamente su contenido mediante JavaScript y AJAX en lugar de recargar la página. Ventajas: experiencia fluida tipo app, menor tráfico, mejor rendimiento percibido, separación clara entre front-end y API.",
    "explanation": "Las SPAs evitan recargas completas, mejorando la experiencia de usuario y reduciendo la carga del servidor."
  },
  "310-programacion ii-desarrollo-describa el concepto de desarrollo de aplicaciones multiplataforma y men": {
    "reference": "El desarrollo multiplataforma permite crear aplicaciones que funcionan en múltiples plataformas (Android, iOS, web) con un mismo código base. Herramientas comunes: Flutter (Dart, Google) y React Native (JavaScript, Facebook), que compilan a nativo.",
    "explanation": "Reduce tiempo y costos de desarrollo al reutilizar el mismo código en distintas plataformas móviles."
  },
