  "341-estructura de datos-desarrollo-describe el proceso de analisis de sistemas y las etapas clave involucra": {
    "reference": "El análisis de sistemas es el proceso de estudiar un problema o necesidad, identificar requisitos y proponer una solución técnica. Etapas: 1) Estudio preliminar (viabilidad), 2) Análisis de requisitos (funcionales y no funcionales), 3) Diseño (arquitectura, modelos), 4) Implementación, 5) Pruebas, 6) Despliegue y 7) Mantenimiento.",
    "explanation": "El análisis precede al diseño: sin comprender el problema no se puede proponer una solución correcta."
  },
  "342-estructura de datos-desarrollo-explica la importancia de realizar un analisis de costo beneficio en el ": {
    "reference": "El análisis de costo-beneficio compara los costos (desarrollo, hardware, formación, mantenimiento) con los beneficios esperados (ahorro de tiempo, ingresos, productividad). Se realiza estimando costos y beneficios en valor presente (VAN, TIR, ROI). Si los beneficios superan los costos, el proyecto es viable financieramente.",
    "explanation": "Sin este análisis, una organización podría invertir en proyectos que nunca recuperen su inversión."
  },
  "343-estructura de datos-desarrollo-describe las diferencias entre el modelo de ciclo de vida en cascada y e": {
    "reference": "El modelo en cascada es secuencial y lineal: cada fase (requisitos, diseño, implementación, pruebas, despliegue) debe completarse antes de la siguiente. El enfoque ágil es iterativo e incremental: entrega funcionalidad en ciclos cortos (sprints), permitiendo adaptarse a cambios y recibir retroalimentación continua del cliente.",
    "explanation": "Cascada es rígido y predictivo; ágil es flexible y adaptativo, ideal para requisitos cambiantes."
  },
  "344-estructura de datos-desarrollo-que es un diagrama de flujo de datos dfd y como se utiliza en el analisi": {
    "reference": "Un DFD (Diagrama de Flujo de Datos) representa visualmente cómo fluyen los datos entre procesos, almacenes y entidades externas de un sistema. Componentes: procesos (círculos o rectángulos), flujos de datos (flechas), almacenes de datos (líneas abiertas) y entidades externas (rectángulos). Se usa para entender y comunicar el comportamiento del sistema.",
    "explanation": "El DFD permite visualizar qué datos entran, salen y se transforman en el sistema, facilitando la comunicación con el cliente."
  },
  "345-estructura de datos-desarrollo-cual es la funcion principal de un diagrama de casos de uso en el analis": {
    "reference": "Un diagrama de casos de uso modela la interacción entre actores (usuarios u otros sistemas) y el sistema, mostrando qué funcionalidades ofrece. Se crea identificando actores, casos de uso (funcionalidades), relaciones de inclusión/extensión y se representa con elipses conectadas a figuras de actor.",
    "explanation": "Es la base para la elicitation de requisitos y permite validar con el cliente qué hará el sistema."
  },
  "346-estructura de datos-desarrollo-cual es el proposito de la documentacion en el proceso de diseno de sist": {
    "reference": "La documentación en diseño de sistemas permite entender, mantener y transferir el conocimiento sobre el sistema. Tipos comunes: documentación de requisitos (SRS), diseño (arquitectura, diagramas UML, DFD), técnica (APIs, datos), de usuario (manuales, guías), de operaciones (instalación, despliegue).",
    "explanation": "Sin documentación, mantener o evolucionar el sistema sería muy costoso y dependiente de las personas originales."
  },
  "347-estructura de datos-desarrollo-describe las principales diferencias entre un enfoque de diseno de siste": {
    "reference": "El enfoque orientado a objetos organiza el sistema alrededor de objetos que combinan estado y comportamiento, usando UML, clases, herencia y polimorfismo. El enfoque estructurado organiza el sistema en funciones y procesos que transforman datos, usando DFD y diagramas de flujo. OO modela el dominio naturalmente; el estructurado se centra en los procesos.",
    "explanation": "OO favorece reutilización y mantenimiento; el estructurado es más simple pero menos flexible para sistemas complejos."
  },
  "348-estructura de datos-desarrollo-explica como se realiza la evaluacion de viabilidad en un proyecto de di": {
    "reference": "La evaluación de viabilidad analiza si un proyecto debe realizarse. Aspectos clave: viabilidad técnica (¿podemos construirlo?), económica (¿los beneficios superan los costos?), operativa (¿se puede usar en la organización?), legal (¿cumple normas?) y de plazos (¿se puede entregar a tiempo?).",
    "explanation": "Sin viabilidad, se pueden iniciar proyectos técnicamente inviables o financieramente ruinosos."
  },
  "349-estructura de datos-desarrollo-cual es la importancia de la planificacion en el proceso de diseno de si": {
    "reference": "La planificación define alcance, objetivos, tareas, recursos, plazos y riesgos del proyecto. Elementos clave de un plan: WBS (estructura de desglose del trabajo), cronograma (Gantt), presupuesto, asignación de recursos, gestión de riesgos, plan de calidad y comunicación.",
    "explanation": "Sin planificación, los proyectos se desvían en costo y tiempo; la planificación permite control y anticipación de riesgos."
  },
  "350-estructura de datos-desarrollo-describe el papel de un analista de sistemas en el proceso de diseno de ": {
    "reference": "El analista de sistemas estudia los problemas y necesidades de una organización, identifica requisitos y propone soluciones tecnológicas. Habilidades: comunicación, escucha activa, análisis, modelado (UML, DFD), conocimiento técnico y de negocio. Responsabilidades: levantar requisitos, modelar procesos, coordinar con stakeholders y validar soluciones.",
    "explanation": "El analista es puente entre el negocio y el equipo técnico; sin él, los requisitos serían ambiguos o incompletos."
  },
