  "421-programacion para dispositivos moviles i ii-desarrollo-cuales son los tipos de aplicaciones": {
    "reference": "Los tipos de aplicaciones son: 1) Nativas (desarrolladas para una plataforma específica con su lenguaje: Swift/Objective-C en iOS, Kotlin/Java en Android); 2) Híbridas (web envuelta en contenedor nativo: Ionic, Cordova); 3) Web (HTML/CSS/JS ejecutadas en navegador); 4) Multiplataforma (un mismo código compila a nativo: Flutter, React Native).",
    "explanation": "Cada tipo equilibra rendimiento, costo y experiencia de usuario según las necesidades del proyecto."
  },
  "422-programacion para dispositivos moviles i ii-desarrollo-defina el concepto de lenguaje de programacion": {
    "reference": "Un lenguaje de programación es un conjunto de reglas, símbolos y sintaxis que permite escribir instrucciones que la computadora puede ejecutar para resolver problemas. Ejemplos: Java, Kotlin, Swift, Python, C++.",
    "explanation": "Permite al humano comunicarse con la máquina mediante una sintaxis formal que el compilador traduce a código ejecutable."
  },
  "423-programacion para dispositivos moviles i ii-desarrollo-realice la definicion de aplicacion multiplataforma": {
    "reference": "Una aplicación multiplataforma es aquella desarrollada con un único código base que se compila o interpreta para funcionar en múltiples plataformas (Android, iOS, web). Herramientas: Flutter (Dart), React Native (JS), Xamarin (C#), Ionic.",
    "explanation": "Reduce costos y tiempos de desarrollo al reutilizar el mismo código en distintas plataformas."
  },
  "424-programacion para dispositivos moviles i ii-desarrollo-que es el concepto de sistema operativo movil": {
    "reference": "Un sistema operativo móvil es un software que gestiona los recursos hardware y software de un dispositivo móvil (smartphone, tablet, smartwatch). Ejemplos: Android (Google, basado en Linux), iOS (Apple, basado en Darwin), HarmonyOS (Huawei).",
    "explanation": "Sin SO móvil, los dispositivos no podrían ejecutar aplicaciones ni gestionar pantalla, táctil, conectividad ni batería."
  },
  "425-programacion para dispositivos moviles i ii-desarrollo-realice la definicion de aplicacion hibrida": {
    "reference": "Una aplicación híbrida combina tecnologías web (HTML, CSS, JavaScript) con un contenedor nativo que permite ejecutarla como app instalada. Usa frameworks como Ionic, Cordova o Capacitor. Accede a funciones del dispositivo mediante plugins.",
    "explanation": "Aprovecha la portabilidad de las tecnologías web con parte del acceso nativo, aunque el rendimiento es menor que el de una app nativa."
  },
  "426-programacion para dispositivos moviles i ii-desarrollo-realice la definicion de aplicacion nativa": {
    "reference": "Una aplicación nativa es aquella desarrollada específicamente para una plataforma usando su lenguaje y SDK oficiales: Swift/Objective-C para iOS, Kotlin/Java para Android. Ofrece máximo rendimiento y acceso completo al hardware del dispositivo.",
    "explanation": "Las apps nativas tienen el mejor rendimiento y experiencia de usuario, pero requieren desarrollo separado para cada plataforma."
  },
  "427-programacion para dispositivos moviles i ii-desarrollo-cuales son las instrucciones basicas y comunes de un lenguaje de program": {
    "reference": "Las instrucciones básicas y comunes de un lenguaje de programación son: 1) Asignación (variable = valor), 2) Entrada/Salida (leer, escribir, print, input), 3) Aritméticas (suma, resta, multiplicación, división), 4) Control de flujo (if-else, switch), 5) Bucles (for, while), 6) Llamadas a funciones/procedimientos, 7) Declaración de variables/constantes.",
    "explanation": "Estas instrucciones son suficientes para expresar cualquier algoritmo, combinándolas adecuadamente."
  },
  "428-programacion para dispositivos moviles i ii-desarrollo-cuales son las tipos o clases de lenguaje de programacion de alto nivel": {
    "reference": "Las clases o tipos de lenguajes de alto nivel son: 1) Compilados (C, C++, Java a bytecode), 2) Interpretados (Python, JavaScript, Ruby), 3) Híbridos (Java, C# compilan a bytecode que una VM interpreta). También se clasifican por paradigma: POO (Java, C#), funcional (Haskell), multiparadigma (Python, JS).",
    "explanation": "La elección del lenguaje afecta rendimiento, portabilidad y velocidad de desarrollo."
  },
  "429-programacion para dispositivos moviles i ii-desarrollo-que es una base de datos sql": {
    "reference": "Una base de datos SQL (Structured Query Language) es una base de datos relacional que organiza los datos en tablas con filas (registros) y columnas (atributos), relacionadas entre sí mediante claves. Permite consultar y manipular datos con el lenguaje SQL. Ejemplos: SQLite (móvil), MySQL, PostgreSQL, SQL Server.",
    "explanation": "Las bases de datos SQL permiten almacenar, consultar y actualizar datos de forma estructurada y consistente, garantizando integridad referencial."
  },
  "430-programacion para dispositivos moviles i ii-desarrollo-que es la arquitectura mvp": {
    "reference": "La arquitectura MVP (Model-View-Presenter) separa la aplicación en tres capas: Model (datos y lógica de negocio), View (interfaz de usuario que muestra datos y captura eventos), Presenter (intermediario que coordina Model y View, actualizando la vista según los datos). Se diferencia de MVC en que el Presenter maneja toda la lógica de presentación y la View es pasiva.",
    "explanation": "MVP facilita las pruebas unitarias y desacopla la lógica de la interfaz, mejorando mantenibilidad en apps móviles."
  },
