  "461-analisis y diseno de sistemas i-desarrollo-describe el proceso de analisis de sistemas y las etapas clave involucra": {
    "reference": "El análisis de sistemas estudia el problema, identifica requisitos y propone una solución. Etapas: 1) Estudio preliminar (viabilidad), 2) Análisis de requisitos (funcionales y no funcionales), 3) Diseño (lógico y físico), 4) Implementación, 5) Pruebas, 6) Despliegue, 7) Mantenimiento.",
    "explanation": "El análisis precede al diseño y a la implementación; sin entender el problema no se puede proponer la solución correcta."
  },
  "462-analisis y diseno de sistemas i-desarrollo-explica la importancia de realizar un analisis de costo beneficio en el ": {
    "reference": "El análisis costo-beneficio compara los costos del proyecto (desarrollo, hardware, capacitación, mantenimiento) con los beneficios esperados (ahorro, ingresos, eficiencia). Se calcula con indicadores como VAN, TIR, ROI y período de retorno. Si los beneficios superan los costos (VAN>0), el proyecto es financieramente viable.",
    "explanation": "Sin este análisis, una organización podría invertir en proyectos que nunca recuperen la inversión."
  },
  "463-analisis y diseno de sistemas i-desarrollo-describe las diferencias entre el modelo de ciclo de vida en cascada y e": {
    "reference": "El modelo en cascada es secuencial y rígido: cada fase (requisitos, diseño, implementación, pruebas, despliegue) debe completarse antes de la siguiente, con poca flexibilidad para cambios. El enfoque ágil es iterativo: entrega funcionalidad en ciclos cortos (sprints), se adapta a cambios y recibe retroalimentación continua del cliente.",
    "explanation": "Cascada es adecuado para requisitos estables; ágil es mejor para proyectos cambiantes o innovadores."
  },
  "464-analisis y diseno de sistemas i-desarrollo-que es un diagrama de flujo de datos dfd y como se utiliza en el analisi": {
    "reference": "Un DFD (Diagrama de Flujo de Datos) representa cómo fluyen los datos entre procesos, almacenes y entidades externas del sistema. Componentes: procesos (burbujas), flujos de datos (flechas), almacenes de datos (líneas abiertas) y entidades externas (rectángulos). Se usa para entender, comunicar y documentar el flujo de información del sistema.",
    "explanation": "El DFD permite visualizar de forma clara qué datos entran, salen y se transforman en el sistema."
  },
  "465-analisis y diseno de sistemas i-desarrollo-cual es la funcion principal de un diagrama de casos de uso en el analis": {
    "reference": "Un diagrama de casos de uso modela las interacciones entre actores (usuarios u otros sistemas) y las funcionalidades (casos de uso) que el sistema ofrece. Se crea identificando actores, casos de uso, sus relaciones de inclusión/extensión y se representa con elipses y figuras de actor conectadas por líneas.",
    "explanation": "Es la base para la elicitation de requisitos y permite validar con el cliente qué funcionalidades tendrá el sistema."
  },
  "466-analisis y diseno de sistemas i-desarrollo-cual es el proposito de la documentacion en el proceso de diseno de sist": {
    "reference": "La documentación permite entender, mantener, transferir y operar el sistema a lo largo del tiempo. Tipos comunes: documentación de requisitos (SRS), diseño (arquitectura, UML, DFD), técnica (APIs, modelos de datos), de usuario (manuales), de operaciones (instalación, despliegue) y de mantenimiento.",
    "explanation": "Sin documentación, el sistema sería opaco y costoso de mantener o evolucionar."
  },
  "467-analisis y diseno de sistemas i-desarrollo-describe las principales diferencias entre un enfoque de diseno de siste": {
    "reference": "El enfoque orientado a objetos organiza el sistema alrededor de objetos (estado + comportamiento), usando clases, herencia, polimorfismo, UML. El enfoque estructurado se centra en funciones y procesos que transforman datos, usando DFD y diagramas de flujo. OO modela el dominio de forma natural; el estructurado enfatiza los procesos.",
    "explanation": "OO favorece reutilización y mantenibilidad; el estructurado es más simple pero menos flexible para sistemas complejos."
  },
  "468-analisis y diseno de sistemas i-desarrollo-explica como se realiza la evaluacion de viabilidad en un proyecto de di": {
    "reference": "La evaluación de viabilidad analiza si el proyecto debe realizarse considerando aspectos: técnico (¿podemos construirlo con la tecnología disponible?), económico (¿beneficios > costos?), operativo (¿encaja en la organización?), legal (¿cumple normas?), plazos (¿se entrega a tiempo?) y social/ambiental.",
    "explanation": "Sin viabilidad, los proyectos pueden fracasar por inviabilidad técnica o económica después de invertir recursos."
  },
  "469-analisis y diseno de sistemas i-desarrollo-cual es la importancia de la planificacion en el proceso de diseno de si": {
    "reference": "La planificación define alcance, objetivos, tareas, recursos, plazos, presupuesto y riesgos del proyecto. Elementos clave: WBS (estructura de desglose del trabajo), cronograma (Gantt), presupuesto, asignación de recursos, plan de calidad, gestión de riesgos y plan de comunicación.",
    "explanation": "Sin planificación, los proyectos se desvían en costo y tiempo, multiplicando los riesgos."
  },
  "470-analisis y diseno de sistemas i-desarrollo-describe el papel de un analista de sistemas en el proceso de diseno de ": {
    "reference": "El analista de sistemas estudia los problemas y necesidades de una organización, identifica requisitos y propone soluciones tecnológicas viables. Habilidades: comunicación, escucha activa, análisis, modelado (UML, DFD), conocimiento técnico y del negocio. Responsabilidades: levantar requisitos, modelar procesos, coordinar con stakeholders y validar soluciones.",
    "explanation": "El analista es puente entre el negocio y el equipo técnico; su rol es crítico para el éxito del proyecto."
  },
