  "491-diseno y programacion web ii-desarrollo-explica la diferencia entre html y css y su funcion en el desarrollo web": {
    "reference": "HTML define la estructura y el contenido de una página (texto, imágenes, formularios). CSS define el estilo y la presentación (colores, fuentes, layout, animaciones). HTML es el esqueleto; CSS es la piel y el diseño visual.",
    "explanation": "HTML organiza qué se muestra; CSS define cómo se ve. Separarlos facilita mantenimiento y reutilización."
  },
  "492-diseno y programacion web ii-desarrollo-describe el modelo de caja en css y como afecta al diseno de una pagina ": {
    "reference": "El modelo de caja CSS describe cada elemento HTML como una caja rectangular compuesta por: contenido (content), relleno (padding), borde (border) y margen (margin). Afecta el diseño porque define el tamaño total del elemento, el espacio interior y exterior, y cómo se relaciona con los demás elementos.",
    "explanation": "Comprender el modelo de caja es esencial para controlar layout, separación y alineación de elementos."
  },
  "493-diseno y programacion web ii-desarrollo-que es el dom y como interactua javascript con el para modificar el cont": {
    "reference": "El DOM (Document Object Model) es una representación en árbol de la estructura HTML de una página. JavaScript interactúa con el DOM a través de la API document para acceder, modificar, añadir o eliminar elementos, atributos y contenido dinámicamente sin recargar la página.",
    "explanation": "El DOM permite que JavaScript manipule la página en tiempo real, haciendo sitios dinámicos e interactivos."
  },
  "494-diseno y programacion web ii-desarrollo-explica que son los frameworks de css y menciona dos ejemplos populares": {
    "reference": "Los frameworks de CSS son bibliotecas de estilos y componentes preconstruidos que facilitan el desarrollo responsivo y consistente. Ejemplos populares: Bootstrap (componentes listos y grid responsivo) y Tailwind CSS (utilidades atómicas para diseño personalizado). Otros: Foundation, Bulma, Materialize.",
    "explanation": "Aceleran el desarrollo al ofrecer componentes y patrones consistentes, evitando escribir CSS desde cero."
  },
  "495-diseno y programacion web ii-desarrollo-que es una spa single page application y como se diferencia de una aplic": {
    "reference": "Una SPA (Single Page Application) carga una sola página HTML y actualiza dinámicamente su contenido mediante JavaScript y AJAX en lugar de recargar la página. Se diferencia de una aplicación web tradicional, donde cada interacción recarga la página completa. Las SPA ofrecen experiencia fluida tipo app, menor tráfico y mejor rendimiento percibido.",
    "explanation": "Las SPAs evitan recargas completas, mejorando la experiencia de usuario y reduciendo la carga del servidor."
  },
  "496-diseno y programacion web ii-desarrollo-describe el uso de flexbox en css para crear disenos web": {
    "reference": "Flexbox (Flexible Box Layout) es un módulo de CSS para crear diseños unidimensionales (filas o columnas) flexibles y responsivos. Permite alinear, distribuir espacio, reordenar elementos y adaptarlos automáticamente al contenedor. Usa display: flex y propiedades como justify-content, align-items, flex-direction.",
    "explanation": "Flexbox simplifica la creación de layouts responsivos que antes requerían hacks con float y positioning."
  },
  "497-diseno y programacion web ii-desarrollo-que es el responsive web design y cuales son sus principios fundamentale": {
    "reference": "El Responsive Web Design (RWD) es una técnica que adapta el diseño de una página al tamaño de la pantalla del dispositivo. Principios fundamentales: 1) Grids fluidas (porcentajes en lugar de píxeles fijos), 2) Imágenes flexibles (max-width: 100%), 3) Media queries (CSS condicional según ancho de pantalla), 4) Mobile First (diseñar primero para móvil).",
    "explanation": "Sin responsive design, el sitio se vería roto o sería difícil de usar en móviles, perdiendo usuarios y posicionamiento SEO."
  },
  "498-diseno y programacion web ii-desarrollo-explica como funciona ajax y su importancia en el desarrollo web": {
    "reference": "AJAX (Asynchronous JavaScript And XML) permite a una página web intercambiar datos con el servidor en segundo plano, sin recargar la página. Se usa para cargar contenido dinámico, validar formularios, autocomplete, notificaciones en tiempo real. Se implementa con el objeto XMLHttpRequest o, modernamente, con fetch(). Es importante porque mejora la experiencia del usuario al permitir actualizaciones parciales.",
    "explanation": "AJAX hace que las páginas se sientan dinámicas e interactivas, sin las pausas de recarga completa."
  },
  "499-diseno y programacion web ii-desarrollo-que es un preprocesador de css y cuales son sus ventajas menciona un eje": {
    "reference": "Un preprocesador de CSS es una herramienta que extiende CSS con características avanzadas (variables, mixins, anidamiento, funciones, herencia) y luego compila a CSS estándar. Ventajas: código más limpio, modular, mantenible y reutilizable. Ejemplo popular: Sass (Syntactically Awesome Style Sheets). Otros: LESS, Stylus.",
    "explanation": "Permiten escribir CSS más estructurado y reutilizable, reduciendo duplicación y facilitando el mantenimiento."
  },
  "500-diseno y programacion web ii-desarrollo-describe el concepto de mobile first en el diseno web": {
    "reference": "El concepto de \"Mobile First\" en diseño web consiste en diseñar primero la versión para móviles y luego escalar hacia tablets y escritorio. Se basa en priorizar lo esencial (mayoría del tráfico es móvil), mejorar el rendimiento en conexiones lentas, y usar media queries con min-width para añadir progresivamente características en pantallas mayores.",
    "explanation": "Diseñar primero para móvil obliga a enfocarse en lo esencial y mejora el SEO, ya que Google indexa primero la versión móvil."
  },
