  "531-base de datos i-desarrollo-fundamentos de bases de datos": {
    "reference": "Los fundamentos de bases de datos incluyen: 1) Modelo de datos (relacional, jerárquico, en red, orientado a objetos); 2) Esquema (estructura lógica) e instancia (datos en un momento); 3) Lenguajes: DDL (definir), DML (manipular), DCL (control), TCL (transacciones); 4) Restricciones de integridad (clave primaria, foránea, unicidad, no nulo).",
    "explanation": "Sin comprender estos fundamentos, no se puede diseñar ni gestionar correctamente una base de datos."
  },
  "532-base de datos i-desarrollo-que es una base de datos": {
    "reference": "Una base de datos es un conjunto organizado de datos estructurados, almacenados en un sistema informático, accesible de forma eficiente y compartible entre múltiples usuarios. Se gestiona mediante un Sistema Gestor de Bases de Datos (SGBD) que permite definir, construir y manipular los datos.",
    "explanation": "Sin bases de datos, los datos estarían dispersos en archivos sin estructura ni control, imposibles de consultar o mantener eficientemente."
  },
  "533-base de datos i-desarrollo-por que interesa usar una base de datos": {
    "reference": "Interesa usar una base de datos porque: 1) Evita redundancia e inconsistencia de datos, 2) Permite compartir datos entre usuarios y aplicaciones, 3) Garantiza integridad mediante restricciones, 4) Ofrece seguridad y control de acceso, 5) Permite recuperación ante fallos, 6) Independencia lógica y física de los datos, 7) Soporta transacciones ACID.",
    "explanation": "Las bases de datos resuelven los problemas de los archivos planos: redundancia, inconsistencia, falta de seguridad y dificultad de consulta."
  },
  "534-base de datos i-desarrollo-modelos de bases de datos": {
    "reference": "Los modelos de bases de datos son: 1) Jerárquico (estructura de árbol, padre-hijo), 2) En red (grafo, varios padres e hijos), 3) Relacional (tablas con filas y columnas, el más usado), 4) Orientado a objetos (objetos y clases), 5) Objeto-relacional (híbrido), 6) NoSQL (documentos, clave- valor, grafos, columnas), 7) Distribuido.",
    "explanation": "Cada modelo responde a necesidades distintas de estructura, escalabilidad y rendimiento."
  },
  "535-base de datos i-desarrollo-bases de datos relacionales": {
    "reference": "Las bases de datos relacionales organizan los datos en tablas bidimensionales (relaciones) formadas por filas (tuplas) y columnas (atributos). Las tablas se relacionan mediante claves primarias y foráneas. Soportan SQL para consultar y manipular datos, garantizan integridad referencial y propiedades ACID. Ejemplos: MySQL, PostgreSQL, Oracle, SQL Server.",
    "explanation": "Son el modelo dominante por su simplicidad, rigor matemático y madurez; ideales para datos estructurados con relaciones claras."
  },
  "536-base de datos i-desarrollo-sistemas gestores de base de datos": {
    "reference": "Un Sistema Gestor de Bases de Datos (SGBD/DBMS) es un software que permite crear, mantener y administrar bases de datos, ofreciendo un lenguaje de consulta (SQL), control de concurrencia, recuperación ante fallos, seguridad, integridad y optimización de consultas. Ejemplos: MySQL, PostgreSQL, Oracle, SQL Server, MongoDB.",
    "explanation": "Sin un SGBD, las aplicaciones tendrían que gestionar ellas mismas el almacenamiento, concurrencia y recuperación de datos, lo cual es inviable."
  },
  "537-base de datos i-desarrollo-diseno y creacion de una base de datos": {
    "reference": "El diseño y creación de una base de datos sigue estas fases: 1) Análisis de requisitos (qué datos almacenar), 2) Diseño conceptual (modelo ER), 3) Diseño lógico (esquema relacional, normalización a 3FN), 4) Diseño físico (índices, particiones, almacenamiento), 5) Implementación en el SGBD (CREATE TABLE), 6) Carga de datos, 7) Pruebas y optimización.",
    "explanation": "Un buen diseño evita redundancia, anomalías de actualización y problemas de rendimiento; la normalización es clave."
  },
  "538-base de datos i-desarrollo-base de datos espaciales": {
    "reference": "Una base de datos espacial almacena datos georreferenciados (con coordenadas geográficas) y permite consultas espaciales (distancia, áreas, superposición). Usa tipos de datos especiales (punto, línea, polígono) e índices espaciales (R-tree). Ejemplos: PostGIS (extensión de PostgreSQL), Oracle Spatial, SQL Server Spatial.",
    "explanation": "Permiten aplicaciones GIS (Sistemas de Información Geográfica): mapas, rutas, análisis territorial, catastro, navegación GPS."
  },
  "539-base de datos i-desarrollo-que es arquitectura dual en sgbd": {
    "reference": "La arquitectura dual en un SGBD se refiere a la separación entre el nivel interno (almacenamiento físico de los datos) y el nivel externo (la vista que ve cada usuario o aplicación). Esta separación garantiza independencia física de los datos: cambios en el almacenamiento no afectan a las aplicaciones.",
    "explanation": "La arquitectura dual proporciona independencia física: cambios en el hardware o almacenamiento no requieren modificar las aplicaciones."
  },
  "540-base de datos i-desarrollo-que es arquitectura en capas sgbd": {
    "reference": "La arquitectura en capas de un SGBD organiza el sistema en tres niveles: 1) Nivel externo (vistas de los usuarios), 2) Nivel conceptual (esquema lógico global), 3) Nivel interno (esquema físico). Esta separación garantiza independencia lógica (cambios en el esquema conceptual no afectan a las vistas externas) y física (cambios en el almacenamiento no afectan al esquema conceptual).",
    "explanation": "La arquitectura en 3 capas permite modificar un nivel sin afectar a los demás, facilitando mantenimiento y evolución."
  },
