  "561-gestion y mejoramiento de la calidad de software-desarrollo-explica el ciclo de vida del desarrollo de software y describe cada una ": {
    "reference": "El ciclo de vida del desarrollo de software (SDLC) incluye las fases: 1) Requisitos (levantamiento y análisis), 2) Diseño (arquitectura, alto y bajo nivel), 3) Implementación (codificación), 4) Pruebas (unitarias, integración, sistema, aceptación), 5) Despliegue (instalación en producción), 6) Mantenimiento (correctivo, adaptativo, perfectivo).",
    "explanation": "Cada fase produce entregables verificables que alimentan la siguiente; saltarse fases aumenta el riesgo de fallos."
  },
  "562-gestion y mejoramiento de la calidad de software-desarrollo-describe como funciona la metodologia agil scrum y menciona los roles pr": {
    "reference": "Scrum es un marco ágil basado en iteraciones llamadas sprints (1-4 semanas). Roles principales: Product Owner (define prioridades del backlog), Scrum Master (facilita el proceso y elimina impedimentos) y Equipo de Desarrollo (construye el producto). Ceremonias: Sprint Planning, Daily Scrum, Sprint Review y Sprint Retrospective.",
    "explanation": "Scrum permite entregar valor de forma incremental y adaptarse a cambios mediante ciclos cortos de retroalimentación."
  },
  "563-gestion y mejoramiento de la calidad de software-desarrollo-que es la gestion de riesgos en proyectos de software y cuales son las p": {
    "reference": "La gestión de riesgos identifica, analiza y mitiga los riesgos del proyecto. Etapas: 1) Identificación de riesgos, 2) Análisis cualitativo y cuantitativo (probabilidad e impacto), 3) Planificación de respuestas (evitar, mitigar, transferir, aceptar), 4) Seguimiento y control de riesgos durante el proyecto.",
    "explanation": "Sin gestión de riesgos, los problemas aparecen tarde y sin plan de contingencia, multiplicando su impacto."
  },
  "564-gestion y mejoramiento de la calidad de software-desarrollo-explica la importancia del aseguramiento de calidad qa en el desarrollo ": {
    "reference": "El Aseguramiento de Calidad (QA) garantiza que el software cumpla los requisitos y estándares definidos. Técnicas comunes: revisiones de código, pruebas unitarias, de integración, de regresión, de rendimiento, de seguridad; análisis estático (SonarQube), integración continua (CI), pruebas automatizadas y revisiones por pares.",
    "explanation": "QA previene defectos en lugar de solo detectarlos, reduciendo costos y mejorando la satisfacción del cliente."
  },
  "565-gestion y mejoramiento de la calidad de software-desarrollo-que es la integracion continua ci y cual es su impacto en la calidad del": {
    "reference": "La integración continua (CI) consiste en integrar el código de todos los desarrolladores frecuentemente (varias veces al día) en un repositorio compartido, ejecutando builds y pruebas automatizadas en cada integración. Impacto: detecta errores temprano, reduce conflictos de integración, mejora calidad y permite despliegues más rápidos y confiables.",
    "explanation": "Sin CI, los errores se detectan tarde en el ciclo, cuando corregirlos es costoso y arriesgado."
  },
  "566-gestion y mejoramiento de la calidad de software-desarrollo-describe el proceso de ingenieria de requisitos y explica la diferencia ": {
    "reference": "La ingeniería de requisitos es el proceso de elicitar, analizar, documentar, validar y gestionar los requisitos del sistema. Requisitos funcionales describen lo que el sistema debe HACER (funciones, comportamientos). Requisitos no funcionales describen CÓMO debe hacerlo (rendimiento, seguridad, usabilidad, disponibilidad).",
    "explanation": "Los funcionales definen comportamiento; los no funcionales definen atributos de calidad; ambos son necesarios para un sistema completo."
  },
  "567-gestion y mejoramiento de la calidad de software-desarrollo-explica como se utiliza la tecnica de estimacion de puntos de historia e": {
    "reference": "La estimación por puntos de historia (story points) asigna a cada historia de usuario un valor relativo que combina esfuerzo, complejidad e incertidumbre. Se usa planning poker para llegar a consenso. Los puntos no son horas, sino unidades relativas. La velocidad del equipo (puntos por sprint) permite planificar cuánto trabajo puede entregar en futuros sprints.",
    "explanation": "Permite estimar sin fijar plazos exactos, basándose en experiencia relativa del equipo; es más realista que estimar horas."
  },
  "568-gestion y mejoramiento de la calidad de software-desarrollo-que es el backlog en scrum y como se priorizan los elementos dentro de e": {
    "reference": "El backlog (Product Backlog) en Scrum es la lista priorizada de todas las funcionalidades, mejoras y correcciones deseadas para el producto. Lo prioriza el Product Owner según valor para el negocio, dependencias y riesgo. En cada Sprint Planning se seleccionan los ítems de mayor prioridad para el Sprint Backlog.",
    "explanation": "El backlog evoluciona continuamente; sin priorización clara, el equipo trabajaría en lo menos valioso."
  },
  "569-gestion y mejoramiento de la calidad de software-desarrollo-describe la importancia del control de versiones en el desarrollo de sof": {
    "reference": "El control de versiones gestiona los cambios en el código fuente a lo largo del tiempo, permitiendo recuperar versiones anteriores, ramificar (branch) para nuevas características, fusionar (merge) cambios y trabajar en paralelo. Herramientas comunes: Git (estándar de facto), Subversion (SVN), Mercurial, Perforce. Plataformas: GitHub, GitLab, Bitbucket.",
    "explanation": "Sin control de versiones, los cambios se perderían, los equipos colisionarían y sería imposible revertir errores."
  },
  "570-gestion y mejoramiento de la calidad de software-desarrollo-explica el concepto de deuda tecnica en el desarrollo de software y como": {
    "reference": "La deuda técnica es el costo implícito de un desarrollo rápido o imperfecto que deberá pagarse más adelante con retrabajo. Tipos: deuda intencional (decidida por presión de plazo), involuntaria (por falta de conocimiento). Se gestiona midiéndola (por code smells, duplicación), documentándola, reservando tiempo en cada sprint para refactorización y priorizando su pago en el backlog.",
    "explanation": "Ignorar la deuda técnica la hace crecer hasta el punto de hacer el sistema inmantenible; pagarla periódicamente mantiene el código sano."
  },
