  "641-analisis y diseno de sistemas ii-desarrollo-describe el ciclo de vida del desarrollo de sistemas y explicalo breveme": {
    "reference": "El ciclo de vida del desarrollo de sistemas (SDLC) es el proceso estructurado para construir y mantener sistemas. Fases clave: 1) Planificación, 2) Análisis de requisitos, 3) Diseño (lógico y físico), 4) Implementación (codificación), 5) Pruebas, 6) Despliegue, 7) Mantenimiento. Cada fase produce entregables que alimentan la siguiente.",
    "explanation": "El SDLC estructura el desarrollo para evitar caos; cada fase tiene objetivos y entregables definidos."
  },
  "642-analisis y diseno de sistemas ii-desarrollo-que es un diagrama de flujo de datos dfd y como se utiliza en el analisi": {
    "reference": "Un DFD (Diagrama de Flujo de Datos) representa cómo fluyen los datos entre procesos, almacenes y entidades externas del sistema. Componentes: procesos (burbujas), flujos de datos (flechas), almacenes de datos (líneas abiertas) y entidades externas (rectángulos). Ejemplo: un sistema de ventas tendría entidades Cliente y Proveedor, procesos como 'Procesar pedido' y almacenes como 'Inventario'.",
    "explanation": "El DFD permite visualizar el flujo de información y validar con el cliente el comportamiento del sistema."
  },
  "643-analisis y diseno de sistemas ii-desarrollo-explica el concepto de modularidad en el diseno de sistemas por que es i": {
    "reference": "La modularidad es la división de un sistema en módulos o componentes más pequeños y manejables, cada uno con una responsabilidad específica. Es importante porque: facilita el desarrollo en paralelo por equipos distintos, simplifica el mantenimiento (cambios aislados), mejora la reutilización, permite pruebas unitarias y reduce la complejidad cognitiva.",
    "explanation": "Sin modularidad, los sistemas serían monolíticos, difíciles de mantener y de probar; la modularidad reduce acoplamiento y aumenta cohesión."
  },
  "644-analisis y diseno de sistemas ii-desarrollo-que implica la ingenieria de requisitos en el analisis y diseno de siste": {
    "reference": "La ingeniería de requisitos es el proceso de elicitar, analizar, documentar, validar y gestionar los requisitos del sistema durante todo su ciclo de vida. Es crucial porque: alinea expectativas con stakeholders, evita ambigüedades, reduce cambios tardíos, fundamenta el diseño y las pruebas, y sirve como contrato entre cliente y equipo.",
    "explanation": "Sin ingeniería de requisitos, los proyectos sufren desviaciones de alcance, sobrecostos y entregas que no satisfacen al cliente."
  },
  "645-analisis y diseno de sistemas ii-desarrollo-describe las principales actividades que se llevan a cabo en la fase de ": {
    "reference": "Las actividades de la fase de pruebas incluyen: 1) Planificación de pruebas (estrategia, alcance, recursos), 2) Diseño de casos de prueba, 3) Ejecución de pruebas (unitarias, integración, sistema, aceptación, regresión, rendimiento, seguridad), 4) Reporte y seguimiento de defectos, 5) Corrección y re-prueba. Objetivo principal: garantizar que el sistema funciona correctamente y cumple los requisitos.",
    "explanation": "Las pruebas detectan defectos antes de que lleguen a producción, reduciendo costos y mejorando la calidad."
  },
  "646-analisis y diseno de sistemas ii-desarrollo-que es uml lenguaje de modelado unificado y como se utiliza en el analis": {
    "reference": "UML (Lenguaje de Modelado Unificado) es una notación gráfica estándar para modelar sistemas orientados a objetos. Diagramas principales: casos de uso (interacción actor-sistema), clases (estructura), secuencia (interacción temporal entre objetos), actividad (flujo de trabajo), estados (ciclo de vida de un objeto), componentes (módulos físicos), despliegue (distribución en hardware).",
    "explanation": "UML permite comunicar el diseño entre analistas, desarrolladores y clientes de forma visual y estandarizada."
  },
  "647-analisis y diseno de sistemas ii-desarrollo-cual es el proposito de la fase de implementacion en el ciclo de vida de": {
    "reference": "La fase de implementación traduce el diseño en código fuente ejecutable. Actividades: configuración del entorno de desarrollo, codificación según estándares, integración con control de versiones, revisiones de código, ejecución de pruebas unitarias, preparación del despliegue y documentación técnica.",
    "explanation": "Sin implementación, el diseño solo queda en papel; es la fase donde el sistema cobra vida."
  },
  "648-analisis y diseno de sistemas ii-desarrollo-que es la reingenieria de sistemas y cuando podria ser necesaria proporc": {
    "reference": "La reingeniería de sistemas es la revisión y mejora de un sistema existente para adaptarlo a nuevas necesidades o tecnologías. Es necesaria cuando: el sistema es legacy (obsoleto), no escala, es difícil de mantener, no cumple nuevos requisitos regulatorios, o cambia la tecnología subyacente. Ejemplo: migrar un sistema monolítico de COBOL a microservicios en la nube.",
    "explanation": "La reingeniería extiende la vida útil del sistema aprovechando el conocimiento de negocio ya codificado."
  },
  "649-analisis y diseno de sistemas ii-desarrollo-describe el proposito de la fase de analisis en el ciclo de vida del des": {
    "reference": "La fase de análisis estudia el problema y las necesidades del sistema actual. Actividades: levantamiento de requisitos (entrevistas, encuestas, observación), modelado del negocio (DFD, casos de uso), análisis de viabilidad (técnica, económica, operativa), definición del alcance, documentación del SRS (Software Requirements Specification) y validación con stakeholders.",
    "explanation": "El análisis alinea el proyecto con las necesidades reales del negocio; sin él, el equipo construiría la solución incorrecta."
  },
  "650-analisis y diseno de sistemas ii-desarrollo-cual es la importancia de la comunicacion efectiva en el analisis y dise": {
    "reference": "La comunicación efectiva es crítica porque: alinea expectativas entre cliente y equipo, evita ambigüedades en requisitos, facilita la validación continua, reduce conflictos, mejora la satisfacción del cliente y permite detectar problemas a tiempo. Los analistas pueden mejorar la comunicación usando: lenguaje claro y no técnico con stakeholders, escucha activa, validación periódica con prototipos, documentación visual (UML, DFD) y reuniones estructuradas.",
    "explanation": "Sin comunicación efectiva, los requisitos se malinterpretan y el sistema entregado no satisface al cliente."
  },
