  "735-emprendimiento productivo-cuestionario de emprendimiento-cuales son tus principales habilidades": {
    "reference": "c) Ser cuidadoso en los pequeños detalles y estar siempre orientado al éxito.",
    "explanation": "La atención al detalle y la orientación al éxito son habilidades clave del emprendedor: distinguen al amateur del profesional."
  },
  "736-emprendimiento productivo-cuestionario de emprendimiento-sabes como promover un negocio": {
    "reference": "c) Sí, conozco los productos y servicios que voy a ofrecer, así como las necesidades de mi mercado.",
    "explanation": "Conocer el producto y el mercado permite diseñar estrategias de promoción efectivas, sin desperdiciar recursos en campañas mal dirigidas."
  },
  "737-emprendimiento productivo-cuestionario de emprendimiento-mi verdadera pasion la podria encontrar en resultados mayoria de a estas": {
    "reference": "a) Aquellas cosas de la vida que siempre he querido hacer y nunca he tenido tiempo.",
    "explanation": "La pasión suele estar en aquello que postergamos por falta de tiempo; emprenderlo puede ser el motor de un negocio exitoso. Interpretación de resultados Resultado 1: Mayoría de A: Estás listo para emprender. Tu segunda pasión está ligada a la forma de hacer negocio. Tienes claro en qué negocio quieres incursionar; el siguiente paso es aterrizar la idea en papel, definir si buscarás socios, desarrollar tu plan de negocio e imaginar cómo quieres tu espacio de trabajo. Esta respuesta indica preparación: ya pasaste la fase de duda y debes avanzar hacia la planificación formal. Resultado 2: Mayoría de B: Cuentas con la capacidad y visión para emprender. La edad no es limitante; complementa tu experiencia con lo que más te gusta hacer. Si ya te decidiste, estructura y define claramente tus gustos y pasiones; elige la que más te convenza y analiza tu mercado objetivo. Esta respuesta indica potencial: debes concretar tu pasión y formalizarla en un plan para evitar dispersión. Resultado 3: Mayoría de C: A pesar de tener la inquietud, te falta descubrir aquello que te apasione y te impulse a emprender. Analiza cuáles son tus verdaderas pasiones preguntándote: ¿qué es lo que más me gusta hacer? En la respuesta encontrarás que no solo puedes dedicar tu tiempo a estar tras un escritorio. Esta respuesta indica que aún estás en fase exploratoria; debes conocerte mejor antes de arriesgarte."
  },
